_Market _$MarketFromJson(Map<String, dynamic> json) => _Market(
  id: json['id'] as String,
  name: json['name'] as String,
  currency: $enumDecode(
    _$CurrencyCodeEnumMap,
    json['currency'],
    unknownValue: CurrencyCode.unknown,
  ),
  defaultLocale: $enumDecode(
    _$LocaleCodeEnumMap,
    json['default_locale'],
    unknownValue: LocaleCode.unknown,
  ),
  taxInclusive: json['tax_inclusive'] as bool,
  isDefault: json['default'] as bool,
  countryCodes: (json['country_codes'] as List<dynamic>)
      .map((e) => $enumDecode(_$CountryCodeEnumMap, e))
      .toList(),
  countryIsos: (json['country_isos'] as List<dynamic>)
      .map((e) => e as String)
      .toList(),
  supportedLocales: (json['supported_locales'] as List<dynamic>)
      .map((e) => $enumDecode(_$LocaleCodeEnumMap, e))
      .toList(),
  countries: (json['countries'] as List<dynamic>?)
      ?.map((e) => Country.fromJson(e as Map<String, dynamic>))
      .toList(),
);

Map<String, dynamic> _$MarketToJson(_Market instance) => <String, dynamic>{
  'id': instance.id,
  'name': instance.name,
  'currency': instance.currency.toJson(),
  'default_locale': instance.defaultLocale.toJson(),
  'tax_inclusive': instance.taxInclusive,
  'default': instance.isDefault,
  'country_codes': instance.countryCodes.map((e) => e.toJson()).toList(),
  'country_isos': instance.countryIsos,
  'supported_locales': instance.supportedLocales
      .map((e) => e.toJson())
      .toList(),
  'countries': ?instance.countries?.map((e) => e.toJson()).toList(),
};
